const stsResponse = $input.first().json;
const webhookBody = $('Webhook').first().json.body;

const assumeResult = stsResponse?.AssumeRoleResponse?.AssumeRoleResult;
const credentials = assumeResult?.Credentials;
const assumedRoleUser = assumeResult?.AssumedRoleUser;

// 1. If STS AssumeRole Succeeded (Valid Session Token)
if (credentials?.SessionToken) {
  return {
    success: true,
    status: 'connected',
    roleStatus: 'verified',
    connectionId: webhookBody.connectionId,
    awsAccountId: webhookBody.awsAccountId,
    roleArn: `arn:aws:iam::${webhookBody.awsAccountId}:role/${webhookBody.roleName || 'FinOpsAwsIntegrationRole'}`,
    assumedRoleUserArn: assumedRoleUser?.Arn,
    sessionTokenReceived: true,
    verifiedAt: new Date().toISOString()
  };
}

// 2. If STS Failed / AccessDenied / Stack Not Ready
const errMsg = stsResponse?.ErrorResponse?.Error?.Message || stsResponse?.Error?.Message || stsResponse?.message || 'AWS STS AssumeRole failed: AccessDenied. Please confirm CloudFormation stack creation is CREATE_COMPLETE.';
const errCode = stsResponse?.ErrorResponse?.Error?.Code || stsResponse?.Error?.Code || 'AccessDenied';

return {
  success: false,
  status: 'verification_failed',
  roleStatus: 'failed',
  connectionId: webhookBody.connectionId,
  awsAccountId: webhookBody.awsAccountId,
  roleArn: `arn:aws:iam::${webhookBody.awsAccountId}:role/${webhookBody.roleName || 'FinOpsAwsIntegrationRole'}`,
  lastError: {
    errorCode: errCode,
    message: errMsg
  }
};
